contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint t) public payable {
        uint amount = 10 ether;
        require(address(this).balance >= amount);

        // Move the test contract's block timestamp to t so the fallback call sees it.
        // No cheatcodes are used; we only prepare the value that c will observe.
        // The fallback requires block.timestamp > pastBlockTime.
        uint before = c.pastBlockTime();
        require(t > before);

        // Drive the fallback: this must be a top-level state-changing call.
        (bool ok1, ) = address(c).call{value: amount}("");
        require(ok1);

        uint afterTime = c.pastBlockTime();

        // At the same timestamp, the next call must revert because
        // pastBlockTime = block.timestamp + 1 and the require is strict >.
        (bool ok2, ) = address(c).call{value: amount}("");

        assert(afterTime == block.timestamp + 1 && !ok2);
    }

    receive() external payable {}
}

