contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint64 ts, uint64 bump) public payable {
        require(address(this).balance >= 10 ether);
        require(bump > 0);

        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;
        require(ts > type(uint64).max - bump);
        require(ts > beforePast);

        (bool ok, ) = address(c).call{value: 10 ether}("");

        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        assert(
            ok
            ? (afterPast == uint256(ts) + uint256(bump) + 1 || afterPast > beforePast)
            : (afterPast == beforePast && afterBalance == beforeBalance)
        );
    }

    receive() external payable {}
}

