contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint futureOffset) public payable {
        require(amount >= 10 ether);
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;
        uint pastBefore = c.pastBlockTime();

        // Enforce block.timestamp > pastBlockTime by setting it beyond the current value.
        c.pastBlockTime();
        uint desired = pastBefore + 1;
        if (desired > block.timestamp) {
            require(futureOffset >= desired - block.timestamp);
        }

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint pastAfter = c.pastBlockTime();

        assert(
            (amount != 10 ether || balAfter != balBefore + amount) ||
                (reverted == false && pastAfter > block.timestamp && pastAfter != pastBefore + 1)
        );
    }

    receive() external payable {}
}

