contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amountBefore) public payable {
        require(address(this).balance >= 10 ether);
        require(amountBefore >= 10 ether);

        // If the contract already has a pastBlockTime in the past, a successful
        // fallback call must pay 10 ether and record pastBlockTime > old timestamp.
        uint oldPastBlockTime = c.pastBlockTime();
        uint cBalanceBefore = address(c).balance;

        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint newPastBlockTime = c.pastBlockTime();
        uint cBalanceAfter = address(c).balance;

        if (!reverted) {
            // Successful call guarantees: 10 ether was paid into c, and
            // pastBlockTime is advanced past the old value and past the
            // current block timestamp by at least 1 second.
            assert(cBalanceAfter >= cBalanceBefore + 10 ether);
            assert(newPastBlockTime > oldPastBlockTime);
            assert(newPastBlockTime >= block.timestamp + 1);

            // The fallback transfers the whole balance only on block numbers
            // divisible by 15; otherwise the contract keeps all received funds.
            if (block.number % 15 == 0) {
                assert(cBalanceAfter == 0);
            } else {
                assert(cBalanceAfter == cBalanceBefore + 10 ether);
            }
        } else {
            // A reverted call must leave c's observed state and balance unchanged.
            assert(newPastBlockTime == oldPastBlockTime);
            assert(address(c).balance == cBalanceBefore);
        }
    }

    receive() external payable {}
}

