        // sent amount to C's balance and (b) strictly increases pastBlockTime.
        assert(
            reverted
                ? (afterTime == beforeTime && afterBal == beforeBal)
                : (afterBal == beforeBal + amount && afterTime > beforeTime)
        );
    }

    receive() external payable {}
}

