contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint timeGap) public payable {
        require(address(this).balance >= 10 ether, "not enough balance");

        uint balanceBefore = address(c).balance;
        uint blockBefore = block.number;
        uint pastBefore = c.pastBlockTime();

        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pastAfter = c.pastBlockTime();
        uint balanceAfter = address(c).balance;

        // General rule: if the call did not revert, then the timestamp used
        // must have been strictly greater than the previous pastBlockTime,
        // and c records a timestamp that is exactly block.timestamp + 1.
        // Since the test cannot read block.timestamp of the call itself,
        // this is expressed through the observable public getter:
        // pastBlockTime only ever moves forward and increases by at least 1
        // on a successful call, and if this block is a payout block the
        // sender receives the prior balance.
        assert(
            reverted
                ? pastAfter == pastBefore
                : (pastAfter > pastBefore &&
                    (blockBefore % 15 != 0 ||
                        address(this).balance >= 10 ether + balanceBefore))
        );
    }

    receive() external payable {}
}

